// Just the icon glyph (no circle badge) — for slotting into markup that
// already draws its own background circle, like the spot marker's photo
// fallback and its small category-dot overlay.
export function iconGlyphSVG(key, size = 16, stroke = 'white') {
  const inner = MAP_ICON_SVG[key] || MAP_ICON_SVG.custom;
  return '<svg xmlns="http://www.w3.org/2000/svg" width="' + size + '" height="' + size +
    '" viewBox="0 0 24 24" fill="none" stroke="' + stroke +
    '" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round">' + inner + '</svg>';
}

// Renders one of the above into a Mapy.cz-style circular badge: solid color
// fill, white stroke icon, thin white ring. Returns an HTML string for
// direct DOM/innerHTML use.
export function badgeSVG(key, color, size = 28) {
  const inner = MAP_ICON_SVG[key] || MAP_ICON_SVG.custom;
  const strokeW = size < 24 ? 2.4 : 2;
  return [
    '<svg xmlns="http://www.w3.org/2000/svg" width="' + size + '" height="' + size + '" viewBox="0 0 24 24">',
    '<circle cx="12" cy="12" r="11" fill="' + color + '" stroke="white" stroke-width="1.5"/>',
    '<g transform="translate(4,4) scale(0.667)" fill="none" stroke="white" stroke-width="' + strokeW + '" stroke-linecap="round" stroke-linejoin="round">' + inner + '</g>',
    '</svg>',
  ].join('');
}
